#!/usr/bin/env python3
"""Insertion ciblée des compléments rédigés ; aucune sérialisation du HTML existant."""
from pathlib import Path
import re, json, gzip, hashlib

BASE = Path(__file__).resolve().parent
LOT = BASE.parents[2] / 'LOT_018'
def refs(*ids):
    return '<sup class="s">'+','.join(f'<a href="#s{i}">{i}</a>' for i in ids)+'</sup>'
def para(title, text, *ids):
    return f'<p><strong>{title}</strong> {text}{refs(*ids)}</p>\n'

A = {
'a-semantique': para('Décrire la fonction avant de nommer la maladie.', 'La <em>métamorphopsie</em> est une déformation de ce qui reste visible ; le <em>scotome</em> est une zone du champ dans laquelle la perception est diminuée ou absente. Ces plaintes ne se résument donc pas au même « flou ». Une difficulté à lire, à repérer une marche ou à voir sur le côté explore des fonctions différentes. Faire préciser la situation concrète permet de choisir entre mesure de l’acuité, recherche d’un déficit du champ et exploration maculaire.',2,9)+para('Distinguer installation et découverte.', 'Une perte véritablement instantanée, une aggravation sur plusieurs jours et la découverte fortuite d’un œil anciennement déficitaire ne portent pas la même orientation. Demander ce qui était visible auparavant avec chaque œil aide à reconstruire cette histoire. La durée de la plainte ne suffit pas à dater une lésion si l’autre œil compensait jusque-là.',2,9),
'a-epidemio': para('Le recrutement change les hypothèses.', 'Une consultation de réfraction chez un enfant, une baisse récente chez un porteur de lentilles et une perte indolore chez un adulte myope ne relèvent pas du même raisonnement. Chez l’enfant, l’enjeu supplémentaire est le développement visuel et l’amblyopie. Chez le porteur de lentilles symptomatique, le risque infectieux impose le tri. Chez le myope, une complication rétinienne reste possible malgré une correction efficace. Ces facteurs orientent l’examen, sans fournir un rang de prévalence suisse.',1,9,30)+para('Séparer fréquence et conséquence.', 'L’absence de fréquence chiffrée applicable au patient ne réduit pas l’importance d’un signe d’alarme. À l’inverse, le fait qu’un trouble réfractif soit fréquent ne permet pas d’attribuer une perte nouvelle aux anciennes lunettes. Les sources cliniques et l’enquête de population répondent à des questions différentes : mécanisme à rechercher pour les premières, retentissement déclaré dans une population définie pour la seconde.',1,2,5),
'a-anatomie': para('Relier le siège à la fonction menacée.', 'Dans un décollement rhegmatogène, une déchirure de pleine épaisseur laisse passer du vitré liquéfié sous la rétine neurosensorielle. Le soulèvement s’étend et atteint la vision centrale lorsqu’il intéresse la macula : une bonne lecture initiale n’écarte donc pas une progression dangereuse. Dans une hémorragie vitréenne, le sang masque au contraire la lumière et l’observation du fond d’œil ; il peut cacher la déchirure qui l’a provoqué.',2)+para('Distinguer une optique corrigible d’un développement perturbé.', 'Une image défocalisée peut redevenir nette avec les verres appropriés. Chez l’enfant, une différence persistante de qualité entre les images des deux yeux peut cependant conduire à la suppression cérébrale de l’image la plus floue et à une amblyopie. La mesure de la réfraction explique alors une partie du mécanisme, mais l’acuité après correction et le suivi du développement visuel restent nécessaires.',9,32),
'a-correlation': para('Interpréter une amélioration sans fermer le diagnostic.', 'Le bénéfice d’une correction démontre une composante optique ; il ne démontre pas que la rétine et les voies visuelles sont intactes. À l’inverse, une amélioration anatomique ne garantit pas la récupération des fonctions déjà perdues. Pour chaque mécanisme, comparer l’objectif du traitement — focaliser l’image, réappliquer la rétine ou protéger le nerf — à la fonction effectivement récupérée évite de confondre résultat technique et résultat visuel.',2,9),
'a-urgences': para('La rougeur et la douleur sont des embranchements, pas des filtres de sécurité.', 'Un décollement rétinien et une ischémie artérielle peuvent évoluer sur un œil blanc et indolore. Une douleur déclenchée par les mouvements avec baisse visuelle fait rechercher une neuropathie, même sans anomalie visible de la papille. Sur un œil rouge, une photophobie, une cornée trouble ou une baisse d’acuité imposent d’explorer au-delà d’une conjonctivite. Chez le diabétique, l’absence de douleur peut être trompeuse.',1,2,30)+para('Adapter le tri au patient qui décrit mal sa plainte.', 'Un enfant préverbal, une personne confuse ou une personne qui ne peut pas communiquer ne peut pas fournir les mêmes signes d’alarme verbaux. Les Hôpitaux universitaires de Genève demandent de ne pas banaliser un œil rouge dans ces situations. Une difficulté à obtenir l’histoire ou l’examen n’est donc pas un résultat rassurant ; elle renforce le besoin d’un examen spécialisé adapté.',1),
'a-anamnese': para('Reconstituer une séquence, puis tester sa cohérence.', 'Des corps flottants suivis d’éclairs puis d’une ombre qui progresse évoquent une traction avec déchirure et décollement. Une perte négative monoculaire soudaine puis complètement résolutive évoque notamment une ischémie rétinienne transitoire. Des phénomènes lumineux s’étendant progressivement dans les deux yeux peuvent orienter vers une aura, tandis que de brèves éclipses liées aux changements de position font rechercher un œdème papillaire. Ces descriptions orientent ; elles ne remplacent pas l’examen ni le tri d’un épisode inhabituel.',2)+para('Interroger les gestes récents et les capacités antérieures.', 'Une opération, une injection, un traumatisme même jugé minime et le port de lentilles changent les causes à rechercher. Demander aussi les anciennes acuités et l’existence d’une amblyopie évite de prendre une asymétrie ancienne pour toute l’explication de la plainte nouvelle. Le traitement utilisé pour un ancien épisode ne doit pas être repris automatiquement, en particulier un collyre corticoïde.',1,2,9),
'a-examen': para('Rendre la mesure comparable.', 'Noter l’œil testé, la correction portée, l’échelle, la distance et la qualité de coopération. Une mesure de près dépend de la distance de lecture et de l’accommodation ; une mesure binoculaire peut masquer une mauvaise vision d’un seul œil. Chez l’enfant qui ne lit pas les lettres, adapter les optotypes ou l’évaluation du comportement visuel à ses capacités, sans appliquer indistinctement la norme de l’adulte.',9)+para('Relier le signe observé à l’examen suivant.', 'Une cornée normalement transparente devient trouble lors de certaines atteintes cornéennes ou d’une hypertonie aiguë. Une ulcération épithéliale peut être révélée par la fluorescéine à l’examen adapté ; un infiltrat ou un hypopion doit faire organiser l’avis urgent. Un fond d’œil non visible doit être décrit comme tel : une opacité vitréenne réclame une exploration de ce qu’elle masque, notamment par échographie spécialisée.',1,2),
'a-syndromes': para('Décomposer les tableaux douloureux.', 'La kératite associe volontiers douleur superficielle, photophobie et blépharospasme ; la lampe à fente recherche une lésion cornéenne. La crise de fermeture de l’angle associe plutôt douleur profonde, halos, baisse visuelle et parfois nausées ; le spécialiste confronte pression élevée, cornée œdémateuse et angle fermé. L’uvéite antérieure se caractérise par une inflammation de la chambre antérieure, avec cellules à la lampe à fente et parfois synéchies. Aucun de ces mécanismes ne se déduit de la seule couleur rouge de l’œil.',1,2)+para('Croiser territoire et chronologie.', 'Un déficit homonyme indique une atteinte située après le chiasma ; son début soudain fait rechercher une cause vasculaire. Un déficit bitemporal oriente vers le chiasma et exige une exploration adaptée, notamment compressive. À l’inverse, des symptômes monoculaires n’excluent pas une maladie systémique embolique ou inflammatoire. La localisation dit où chercher ; la chronologie et le contexte disent avec quelle urgence et pour quelle cause.',2),
'a-criteres': para('Évaluer trois concordances.', 'La première est fonctionnelle : le test doit explorer la fonction réellement décrite. La deuxième est anatomique : la lésion observée doit pouvoir produire le territoire du déficit. La troisième est temporelle : une affection ancienne ne suffit pas à expliquer une modification soudaine. Cette grille de raisonnement n’est pas un score validé ; elle sert à repérer une explication incomplète avant d’interrompre le bilan.',2,9)+para('Ne pas transformer un intervalle libre en exclusion.', 'Après une cécité monoculaire transitoire, la récupération peut rendre l’acuité et l’examen intercritique rassurants en apparence. Le diagnostic repose alors particulièrement sur l’histoire et sur la recherche du mécanisme vasculaire ou inflammatoire. De même, une papille normale ne contredit pas à elle seule une névrite rétrobulbaire ; il faut confronter douleurs, champ, réactions pupillaires et imagerie orientée.',2),
'a-explorations': para('Choisir le volume exploré, puis interpréter ce qui manque.', 'La tomographie en cohérence optique centrée sur la macula décrit ses couches et ses anomalies ; celle centrée sur la papille ou les fibres répond à une autre question. La périmétrie documente la fonction du champ, que l’image anatomique ne mesure pas directement. Un résultat normal à un examen centré sur la mauvaise région n’exclut pas la cause suspectée : le compte rendu doit être confronté au territoire symptomatique.',2)+para('Différencier les techniques vasculaires.', 'L’angiographie à la fluorescéine renseigne sur la circulation rétinienne ; celle au vert d’indocyanine explore surtout la circulation choroïdienne. L’angiographie par tomographie en cohérence optique visualise la perfusion sans injection. Leur choix dépend de la question rétinienne ou choroïdienne posée ; aucune ne remplace le bilan neurovasculaire d’une perte monoculaire ischémique suspectée.',2)+para('Quand le fond est masqué, explorer derrière l’opacité.', 'Une hémorragie vitréenne n’est pas un diagnostic causal suffisant. Une déchirure, un décollement ou une rétinopathie proliférante peuvent expliquer le saignement. L’échographie B spécialisée recherche notamment un décollement lorsque la rétine n’est pas visible ; la découverte de sang dans le vitré ne permet pas d’attendre simplement qu’il se résorbe.',2),
'a-algorithme': para('Lorsque plusieurs explications coexistent, traiter la discordance.', 'Si les lunettes améliorent une partie du flou mais qu’un rideau nouveau persiste, poursuivre la filière rétinienne urgente. Si une cataracte est visible mais que la baisse s’est installée brutalement, rechercher une cause aiguë associée. Si l’examen du fond est normal alors que le déficit du champ est homonyme, explorer les voies cérébrales. La branche de décision est déterminée par le signe inexpliqué le plus préoccupant, pas seulement par la première anomalie trouvée.',2,9)+para('Organiser la prochaine étape avant de conclure.', 'Si le patient ne peut pas réaliser les tests, choisir une méthode adaptée ou un avis spécialisé. Si aucune explication concordante n’est obtenue, préciser l’exploration restante et son urgence. Une baisse inexpliquée ou une aggravation ne se résout pas par un renouvellement empirique des lunettes ; une réévaluation doit reprendre le symptôme, la localisation et les causes menaçantes.',1,2,9),
'a-traitement': para('Séparer le geste protecteur du traitement définitif.', 'L’irrigation d’une brûlure commence avant le transfert ; elle n’attend pas l’identification complète du produit. Dans une fermeture de l’angle, la baisse urgente de pression permet de préparer le traitement du blocage, généralement une iridotomie dans le mécanisme pupillaire décrit. Dans un décollement rhegmatogène, le traitement chirurgical doit obturer la déchirure et permettre la réapplication ; une correction optique n’agit pas sur ce mécanisme.',1,2)+para('Vérifier la continuité fonctionnelle.', 'Au retour, le patient doit savoir quel changement impose de revenir : nouvelle ombre, multiplication des corps flottants, douleur, baisse de l’autre œil ou aggravation visuelle. La capacité à lire les consignes et à instiller un traitement doit être prise en compte. Une dilatation peut rendre la conduite temporairement impossible ; organiser un retour compatible avec la vision réelle et les consignes reçues, plutôt que déduire l’aptitude de la seule amélioration ressentie.',30,32),
'a-interactions': para('La conciliation doit inclure les traitements non ophtalmologiques.', 'Une interaction peut modifier l’efficacité du traitement oculaire ou sa toxicité systémique. Les médicaments qui favorisent la perte de potassium justifient une attention particulière lorsque l’acétazolamide ou un corticoïde sont utilisés. Sous antagoniste de la vitamine K, la réponse à la méthylprednisolone peut varier dans les deux sens. La surveillance suit donc le mécanisme de l’interaction et le médicament associé, sans correction forfaitaire de dose.',7,8),
'a-diamox': para('Ne pas confondre baisse de pression et suppression de l’obstacle.', 'Dans une crise par fermeture de l’angle, réduire la production d’humeur aqueuse fait partie du traitement initial. Cela ne prouve pas que l’angle est rouvert ni que le mécanisme pupillaire a disparu. La réponse doit être mesurée et la suite anatomique décidée par l’ophtalmologue ; prolonger empiriquement le traitement systémique ne remplace pas cette étape.',2,7),
'a-corticoides': para('Relier l’urgence à l’indication précise.', 'Le bénéfice attendu dans une artérite à cellules géantes est de limiter la menace ischémique, notamment pour la vision encore préservée ; la récupération d’un déficit constitué ne peut pas être promise. Ce raisonnement ne justifie pas un corticoïde empirique pour toute perte visuelle. Une suspicion d’infection cornéenne ou intraoculaire impose une autre démarche ; les corticoïdes topiques relèvent du spécialiste.',1,2,6),
'a-prevention': para('Dépister ce que le patient ne remarque pas.', 'Chez l’enfant, un œil dominant peut masquer le déficit de l’autre ; le dépistage doit examiner chaque œil et rechercher un strabisme ou une asymétrie. Le traitement précoce d’un trouble réfractif participe à la prévention de l’amblyopie. Le calendrier français figurant dans le référentiel ne devient pas un calendrier suisse : l’organisation pédiatrique locale doit être vérifiée.',9,32)+para('Transformer les signes d’alerte en consignes concrètes.', 'Chez le myope ou après une intervention oculaire, expliquer ce que sont des corps flottants nouveaux, des éclairs et une ombre qui s’étend. Leur apparition impose une évaluation urgente même si le patient lit encore. Chez le porteur de lentilles, une rougeur douloureuse ou une baisse visuelle impose le retrait des lentilles et l’avis spécialisé ; l’usage antérieur sans problème ne protège pas d’un nouvel épisode infectieux.',1,30),
'a-pointscles': para('Raisonner avec la fonction, le siège et le temps.', 'Décrire d’abord ce qui manque : détails, champ, couleurs ou qualité de l’image. Mesurer chaque œil, puis confronter le déficit au siège anatomique et au mode d’installation. Une amélioration avec correction peut coexister avec une maladie ; une apparence normale peut coexister avec une atteinte nerveuse. Le signe qui reste inexpliqué doit guider la suite du bilan.',2,9)+para('Vérifier que la décision change le risque.', 'Devant une menace aiguë, nommer l’action utile : irrigation immédiate, examen rétinien périphérique, mesure instrumentale de pression ou évaluation neurovasculaire urgente. Chez l’enfant, protéger aussi le développement visuel. À la fin de la consultation, préciser le suivi et les signes imposant un retour ; ne pas promettre qu’une correction ou une amélioration anatomique supprime tout risque ultérieur.',1,2,9,30),
'a-pieges': para('Justifier la réponse par le signe décisif.', 'Pour chaque situation, formuler la fonction atteinte, le siège suspecté et l’action qui ne doit pas être retardée. Puis identifier la donnée trompeuse : récupération spontanée, absence de douleur, bonne acuité centrale, fond d’œil normal ou coexistence d’une anomalie fréquente. Cette méthode distingue la reconnaissance d’un terme du raisonnement clinique nécessaire à la décision.',1,2,9)
}

D = {
'dx1-detail1': para('Ne pas confondre les axes de classification.', 'La myopie et l’hypermétropie décrivent la position du foyer au repos ; l’astigmatisme décrit une différence de puissance selon les méridiens. Un même œil peut donc associer une amétropie sphérique et un astigmatisme. L’anisométropie compare les deux yeux : elle peut exister avec ou sans astigmatisme. Enfin, la presbytie concerne la capacité d’accommoder, et non la seule position du foyer de loin.',9,31)+para('Séparer correction et fonction acquise.', 'Une amétropie non corrigée produit une image floue que la correction peut améliorer. Une amblyopie traduit un développement visuel perturbé, particulièrement lorsque les deux yeux ont reçu des images de qualité inégale. Elle doit être recherchée devant une meilleure acuité corrigée insuffisante ; le mot « amblyopie » ne doit toutefois pas dispenser de rechercher une lésion organique.',9,32),
'dx1-detail2': para('L’âge modifie le mécanisme et le risque.', 'L’œil de l’enfant grandit et sa réfraction évolue ; une hypermétropie peut être partiellement compensée par une accommodation importante. Le risque clinique majeur d’un défaut asymétrique non corrigé est alors l’amblyopie. Plus tard, la diminution de l’accommodation peut révéler une hypermétropie jusque-là compensée et aggraver la gêne de près. Une myopisation acquise peut aussi être liée au cristallin, notamment à une cataracte nucléaire.',9)+para('Interpréter le terrain sans inventer une fréquence.', 'Des antécédents familiaux de strabisme, une hypermétropie non corrigée et une baisse visuelle d’origine oculaire font partie des éléments recherchés chez l’enfant selon les Hôpitaux universitaires de Genève. Ces facteurs justifient un examen adapté ; ils ne donnent pas une probabilité chiffrée individuelle. Les sources lues ne fournissent pas de prévalence suisse actuelle des seules amétropies non corrigées.',9,32),
'dx1-detail3': para('Identifier le mécanisme de la myopisation.', 'Une myopie peut résulter d’un allongement axial, d’une courbure cornéenne excessive, d’une augmentation de l’indice du cristallin ou d’un excès accommodatif. Ces mécanismes n’appellent pas le même bilan. Une nouvelle correction négative chez une personne âgée conduit à examiner le cristallin. Une irrégularité cornéenne conduit à explorer la cornée. Une mesure variable chez un enfant impose de tenir compte de l’accommodation.',9)+para('Relier accommodation, fatigue et traitement.', 'L’hypermétrope jeune peut mobiliser l’accommodation même pour la vision de loin. Le travail rapproché ajoute une demande supplémentaire et peut provoquer fatigue, céphalées et flou de près. Un verre convergent réduit l’effort optique nécessaire. Chez le presbyte, une addition positive compense la perte d’accommodation à la distance utile, mais elle ne restaure pas la souplesse du cristallin.',9,31),
'dx1-detail4': para('Rechercher ce qu’une amétropie isolée explique mal.', 'Un défaut réfractif stable ne suffit pas à expliquer une perte instantanée, une ombre qui progresse, une photophobie importante ou une douleur sous lentilles. Chez le myope, la présence d’anciennes lunettes fortes ne doit pas conduire à attribuer des éclairs nouveaux au seul besoin de correction. Chez l’enfant, un strabisme ou une mauvaise fixation réclament une évaluation du développement visuel et de l’œil lui-même.',1,9,30,32)+para('Choisir la filière selon le signe associé.', 'Une douleur et une rougeur sous lentilles font rechercher en urgence une kératite ; des corps flottants nouveaux, des éclairs ou un rideau imposent l’examen rétinien périphérique. Une diplopie ou un strabisme d’apparition soudaine demandent aussi un avis urgent. L’amélioration partielle avec un verre n’annule aucune de ces indications.',1,30,32),
'dx1-detail5': para('Distinguer plainte optique et retentissement.', 'Demander dans quelles tâches la gêne apparaît : lecture, écran, reconnaissance à distance ou passage d’une distance à l’autre. Préciser si le patient enlève ses lunettes pour lire, si la fatigue augmente pendant l’effort rapproché et si les contours restent dédoublés lorsqu’un œil est couvert. Ces éléments orientent vers myopie, effort accommodatif, presbytie ou composante astigmatique, à confirmer par la mesure.',9)+para('Rechercher une histoire visuelle asymétrique.', 'Chez l’enfant, interroger les parents sur la fixation, une déviation, les anciens examens et les corrections réellement portées. Chez l’adulte, rechercher une ancienne occlusion, un strabisme ou une différence durable d’acuité entre les yeux. Une mauvaise vision ancienne peut être liée à l’amblyopie ; toute aggravation récente nécessite néanmoins une nouvelle explication.',9,32),
'dx1-detail6': para('Séparer mesure objective et choix subjectif.', 'L’autoréfractomètre fournit une estimation de la sphère, du cylindre et de son axe. La sphère et le cylindre expriment des puissances en dioptries ; l’axe indique une orientation en degrés. Le contrôle subjectif interpose ensuite différents verres pour déterminer la meilleure acuité et une correction cohérente avec la plainte. La kératométrie mesure la courbure cornéenne ; elle ne mesure pas à elle seule l’ensemble de la réfraction. Une prescription ne repose donc pas sur la seule impression imprimée par l’appareil.',9)+para('Tenir compte de l’accommodation et de la coopération.', 'Chez l’enfant, une accommodation active peut masquer une hypermétropie ou modifier la mesure. Une réfraction sous cycloplégie permet au spécialiste de limiter cet effet, notamment lorsqu’un strabisme est associé. La dilatation de la pupille et le blocage de l’accommodation sont deux effets distincts : constater une grande pupille ne suffit pas à décrire une mesure de réfraction sous cycloplégie.',9,32),
'dx1-detail7': para('Reconnaître les associations plutôt que les cases exclusives.', 'Un myope astigmate peut présenter un flou de loin avec des contours dédoublés ; un hypermétrope presbyte peut cumuler effort de mise au point et gêne accrue de près. Le syndrome fonctionnel doit être confronté à la mesure sphérique et cylindrique, puis à l’acuité corrigée. Les catégories optiques se combinent, alors que les signes d’alarme rétiniens ou infectieux imposent une autre branche de raisonnement.',9)+para('Distinguer le dédoublement de l’image de la déviation des yeux.', 'L’astigmatisme peut produire un dédoublement lié à l’optique d’un œil. Une diplopie liée à l’alignement exige l’examen de la motilité et du strabisme ; son apparition soudaine est un signe d’alarme. Demander l’effet de l’occlusion d’un œil aide à caractériser la plainte, mais ne remplace pas cet examen.',9,32),
'dx1-detail8': para('Exiger une concordance fonctionnelle.', 'Une erreur réfractive mesurée n’est pertinente pour la plainte que si sa correction apporte le bénéfice attendu et si le reste de l’examen est cohérent. Une acuité de loin améliorée ne suffit pas à expliquer une gêne persistante de près : vérifier l’accommodation et l’addition nécessaire. De même, la récupération centrale n’explique pas un déficit du champ ou de nouveaux phosphènes.',9,30)+para('Qualifier le déficit résiduel avant de l’attribuer à l’amblyopie.', 'Chez un patient dont un œil voit moins bien malgré correction, rechercher l’ancienneté, le strabisme, l’asymétrie réfractive et une cause organique. L’amblyopie correspond à une histoire de développement ; elle n’explique pas automatiquement une baisse nouvelle. Chez le myope avec atteinte rétinienne, le plafond d’acuité corrigée peut être limité par la rétine plutôt que par la puissance des verres.',9,32),
'dx1-detail9': para('Interpréter le bilan dans son ordre utile.', 'La mesure objective donne le point de départ. La réfraction subjective recherche la meilleure fonction avec les verres. La confrontation au segment antérieur et au fond d’œil recherche une cause associée. Si la mesure varie, vérifier les conditions et l’accommodation. Si l’acuité reste réduite, cibler l’exploration sur l’anomalie suspectée, au lieu de multiplier indistinctement les examens.',9)+para('Adapter l’examen complémentaire au mécanisme.', 'La kératométrie renseigne sur la courbure de la cornée, tandis que le bilan préopératoire de chirurgie réfractive vérifie aussi son épaisseur et sa compatibilité avec la technique envisagée. L’évaluation d’une myopie avec complications exige l’examen rétinien. Ces objectifs diffèrent : un bilan cornéen satisfaisant ne démontre pas l’absence de lésion rétinienne et une correction réfractive réussie ne constitue pas une exploration du fond d’œil.',9,30,31),
'dx1-detail10': para('Appliquer une logique de discordance.', 'Si un enfant voit correctement avec les deux yeux mais moins bien avec l’un d’eux isolément, poursuivre le bilan de cet œil et du développement visuel. Si un adulte doit retirer ses lunettes de loin pour lire, mesurer aussi la vision de près avant de conclure à une amélioration de sa myopie. Si une nouvelle correction ne restaure qu’une partie de l’acuité, rechercher ce qui limite la récupération avant de prescrire un verre plus puissant.',9,32)+para('Distinguer correction et décision chirurgicale.', 'Si les verres apportent une fonction adaptée, vérifier leur tolérance et le suivi nécessaire. Si le patient souhaite une chirurgie, la question devient celle de la stabilité réfractive, de l’état cornéen, des autres maladies oculaires et des attentes. L’intolérance aux lunettes ne suffit pas, à elle seule, à démontrer l’éligibilité à une technique chirurgicale.',31),
'dx1-detail11': para('Choisir un moyen cohérent avec la cible.', 'Les lunettes ou lentilles corrigent la focalisation ; l’addition de près compense le besoin accommodatif. Chez l’enfant présentant une amblyopie ou un strabisme, la correction peut s’intégrer à un traitement comportant une occlusion prescrite et surveillée. Une intervention sur les muscles oculaires ne remplace pas les lunettes ou l’occlusion lorsqu’elles restent nécessaires. Les objectifs réfractif, binoculaire et développemental doivent donc être distingués.',9,32)+para('Discuter la chirurgie après le bilan.', 'La chirurgie cornéenne modifie la puissance optique ; une technique avec implant peut être envisagée lorsque le laser seul n’est pas adapté. Les Hôpitaux universitaires de Genève demandent une réfraction stable et des caractéristiques cornéennes compatibles ; une maladie oculaire associée peut modifier ou écarter l’indication. La grossesse et l’allaitement sont des périodes durant lesquelles leur information déconseille cette chirurgie. Le choix doit intégrer le résultat attendu et les limites propres à la technique.',31)+para('Définir ce que le suivi doit vérifier.', 'Le suivi porte sur la vision de chaque œil, le confort aux distances utiles, le port effectif de la correction et l’évolution. Chez l’enfant, suivre l’acuité et l’alignement permet de vérifier que le développement visuel progresse. Chez le myope, rappeler que la correction du flou ne supprime pas le risque de complication rétinienne. Un symptôme nouveau modifie la conduite et ne doit pas attendre un contrôle de routine.',9,30,32),
'dx1-detail12': para('Prévenir l’amblyopie sans attendre une plainte.', 'L’enfant peut fonctionner avec l’œil qui voit le mieux et ne pas signaler le déficit de l’autre. Rechercher les antécédents familiaux, une fixation anormale, un strabisme et une différence d’acuité permet d’orienter le dépistage. La correction prescrite doit être réellement portée et son efficacité contrôlée. La prescription d’un patch relève d’une stratégie individualisée ; ce n’est pas un conseil à appliquer indistinctement à toute amétropie.',9,32)+para('Séparer prévention du défaut et prévention de ses complications.', 'Informer sur l’hygiène des lentilles et le retrait en cas de douleur ou de rougeur vise à éviter une complication infectieuse et son retard de traitement. Chez le myope, enseigner les signes de déchirure ou de décollement vise à limiter le retard diagnostique. Ces mesures restent utiles même lorsque la vision avec correction est excellente ; elles ne signifient pas que toute complication est évitable.',1,30),
'dx1-detail13': para('Garder quatre liens de raisonnement.', 'Le foyer au repos explique le choix du verre ; l’accommodation explique une partie des fluctuations et de la gêne de près. L’asymétrie des images chez l’enfant explique le risque d’amblyopie. La meilleure acuité corrigée indique la fonction récupérable par la correction testée. Les symptômes nouveaux, en particulier douleur, éclairs ou rideau, imposent de rechercher une autre affection.',1,9,30)+para('Évaluer le résultat utile.', 'Le succès ne se résume pas au nombre de dioptries prescrit : le patient doit disposer d’une vision adaptée aux tâches, avec un suivi tenant compte de l’âge et des lésions associées. Une correction bien tolérée ne dispense pas du suivi d’une amblyopie ou d’une atteinte rétinienne. Une chirurgie réfractive demande son propre bilan et ne remplace pas cette surveillance.',9,31,32),
'dx1-quiz': para('Répondre en reliant mécanisme et conduite.', 'Pour chaque question, préciser pourquoi le signe est compatible avec le mécanisme proposé et ce qui obligerait à rouvrir le diagnostic. Une réponse correcte sur le type de verre reste insuffisante si elle omet une douleur sous lentilles, un rideau récent ou une asymétrie chez l’enfant. Les explications suivantes conservent cette priorité clinique.',1,9,30,32)
}

