def insert_start(text, id, addition):
    at=text.index('<div id="'+id+'"')
    marker='<div class="corps">'; pos=text.index(marker,at)+len(marker)
    return text[:pos]+'\n<!-- RENFORCEMENT_MEDICAL_20261101 '+id+' -->\n'+addition+text[pos:]

NEW_SOURCES = {
9:'Collège des ophtalmologistes universitaires de France. Référentiel, 6e édition, 2025, chapitre 2 : Réfraction et anomalies de la réfraction. <a href="https://couf.fr/wp-content/uploads/2025/10/CH2_Ophtalmologie_-Sous-legide-du-College-des-ophtalmologistes-universitaires-de-France.pdf">Source</a>. Texte extrait relu le 01.11.2026 : bases optiques, développement, mesure, amétropies, presbytie. Les règles françaises de conduite ne sont pas transposées.',
30:'Hôpitaux universitaires de Genève. Le décollement de rétine, page d’information, mise à jour affichée le 06.05.2025. <a href="https://www.hug.ch/ophtalmologie/decollement-retine">Source</a>. Consultée le 01.11.2026 : mécanisme, symptômes, terrain et urgence.',
31:'Hôpitaux universitaires de Genève. La chirurgie réfractive de l’œil. <a href="https://www.hug.ch/ophtalmologie/chirurgie-refractive-loeil">Source</a>. Consultée le 01.11.2026 : principes optiques, choix du moyen et conditions préopératoires.',
32:'Hôpitaux universitaires de Genève. Strabisme : <a href="https://www.hug.ch/ophtalmologie/facteurs-risque-diagnostic-du-strabisme">facteurs de risque et diagnostic</a> ; <a href="https://www.hug.ch/ophtalmologie/traitements-du-strabisme">traitements</a>. Consultées le 01.11.2026 : examen, urgence, correction, occlusion et limites de la chirurgie.'
}

def run(name,adds,quiz_adds,prefix):
    p=LOT/name;before=gzip.decompress((BASE/(name+'.avant.gz')).read_bytes()).decode();assert p.read_text()==before, 'Ne pas relancer sur un fichier déjà enrichi ou modifié par un autre agent';text=before
    # Le point 13 n'avait aucune fenêtre : simple lien dans la phrase existante.
    id=prefix+'-pointscles' if prefix=='a' else prefix+'-detail13'
    sentence='Une perte brutale ou transitoire' if prefix=='a' else 'Mesurer chaque œil'
    linked=f'<button type="button" class="terme" popovertarget="{id}">{sentence}</button>'
    at=text.index(f'<h2 id="{prefix}-p13">');pos=text.index(sentence,at);text=text[:pos]+text[pos:].replace(sentence,linked,1)
    new=f'<div id="{id}" popover class="fenetre"><div class="barre"><span>Points clés et raisonnement clinique</span><button type="button" popovertarget="{id}" popovertargetaction="hide" aria-label="Fermer">✕</button></div><div class="corps"></div></div>\n'
    anchor='<div id="a-pieges"' if prefix=='a' else '<div id="dx1-quiz"';text=text.replace(anchor,new+anchor,1)
    for id,addition in adds.items():text=insert_start(text,id,addition)
    # Réponses des14questions enrichies en place, sans changer leurs questions.
    matches=list(re.finditer(r'<details class="quiz">.*?</details>',text,re.S));assert len(matches)==14
    for index,m in reversed(list(enumerate(matches))):
        chunk=m.group();cite=[2] if prefix=='a' else [9]
        if prefix=='a' and index in [4,5,6]:cite=[1]
        if prefix=='a' and index==3:cite=[2,6]
        if prefix=='a' and index==8:cite=[5]
        if prefix=='a' and index in [10,11]:cite=[7]
        if prefix=='a' and index==12:cite=[6,8]
        if prefix=='dx1' and index==10:cite=[30]
        if prefix=='dx1' and index==11:cite=[1]
        chunk=chunk.replace('</details>',para('Raisonnement.',quiz_adds[index],*cite)+'</details>');text=text[:m.start()]+chunk+text[m.end():]
    start=text.index('<h2>Sources</h2>');end=text.index('</ol>',start)
    sources=''.join(f'<li id="s{i}" value="{i}">{v}</li>\n' for i,v in NEW_SOURCES.items() if f'id="s{i}"' not in text and (prefix!='a' or i!=31))
    text=text[:end]+sources+text[end:]
    p.write_text(text)
    return {'fichier':name,'sha256_avant':hashlib.sha256(before.encode()).hexdigest(),'sha256_apres':hashlib.sha256(text.encode()).hexdigest(),'octets_avant':len(before.encode()),'octets_apres':len(text.encode()),'fenetres_enrichies':list(adds),'questions_conservees':14,'complements':adds,'reponses_ajoutees':quiz_adds}

if __name__=='__main__':
    results=[run('LOT_018_Phase_A_V0.html',A,QUIZ_A,'a'),run('LOT_018_Phase_B_V0_DX.1.html',D,QUIZ_D,'dx1')]
    (BASE/'ENRICHISSEMENTS_EXACTS.json').write_text(json.dumps(results,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps([{k:v for k,v in r.items() if k not in ['complements','reponses_ajoutees']} for r in results],ensure_ascii=False,indent=2))
